use std::env;
use std::fs;
use std::process;

#[derive(Clone)]
struct Section {
    name: String,
    fields: Vec<(String, String)>,
    inherits: Option<String>,
}

fn parse_quoted(value: &str) -> Result<String, String> {
    let chars: Vec<char> = value.chars().collect();
    if chars.len() < 2 || chars[0] != '"' || chars[chars.len() - 1] != '"' {
        return Err("field values must be quoted".to_string());
    }
    let mut result = String::new();
    let mut index = 1;
    while index + 1 < chars.len() {
        let ch = chars[index];
        if ch == '"' {
            return Err("unexpected quote in field value".to_string());
        }
        if ch == '\\' {
            index += 1;
            if index + 1 >= chars.len() {
                return Err("unterminated escape in field value".to_string());
            }
            let escaped = match chars[index] {
                '"' => '"',
                '\\' => '\\',
                'n' => '\n',
                'r' => '\r',
                't' => '\t',
                '0' => '\0',
                other => return Err(format!("unsupported escape \\{}", other)),
            };
            result.push(escaped);
        } else {
            result.push(ch);
        }
        index += 1;
    }
    Ok(result)
}

fn parse(data: &str) -> Result<Vec<Section>, String> {
    let mut sections: Vec<Section> = Vec::new();
    for (line_number, raw_line) in data.lines().enumerate() {
        let line = raw_line.strip_suffix('\r').unwrap_or(raw_line);
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        if trimmed.starts_with('[') {
            if !trimmed.ends_with(']') || trimmed.len() < 3 {
                return Err(format!("malformed section header on line {}", line_number + 1));
            }
            let name = trimmed[1..trimmed.len() - 1].trim();
            if name.is_empty() || name.contains('[') || name.contains(']') {
                return Err(format!("malformed section header on line {}", line_number + 1));
            }
            if sections.iter().any(|section| section.name == name) {
                return Err(format!("duplicate section '{}'", name));
            }
            sections.push(Section {
                name: name.to_string(),
                fields: Vec::new(),
                inherits: None,
            });
            continue;
        }

        let section = sections
            .last_mut()
            .ok_or_else(|| format!("field outside a section on line {}", line_number + 1))?;
        let (key, raw_value) = trimmed
            .split_once('=')
            .ok_or_else(|| format!("malformed field on line {}", line_number + 1))?;
        let key = key.trim();
        let raw_value = raw_value.trim();
        if key.is_empty() || key.contains(char::is_whitespace) {
            return Err(format!("malformed field on line {}", line_number + 1));
        }
        let value = parse_quoted(raw_value)
            .map_err(|message| format!("{} on line {}", message, line_number + 1))?;
        if key == "inherits" {
            if section.inherits.is_some() {
                return Err(format!("duplicate field 'inherits' in section '{}'", section.name));
            }
            section.inherits = Some(value);
        } else {
            if section.fields.iter().any(|(existing, _)| existing == key) {
                return Err(format!("duplicate field '{}' in section '{}'", key, section.name));
            }
            section.fields.push((key.to_string(), value));
        }
    }
    if sections.is_empty() {
        return Err("no sections found".to_string());
    }
    Ok(sections)
}

fn resolve(index: usize, sections: &[Section]) -> Result<Vec<(String, String)>, String> {
    let section = &sections[index];
    let mut fields = Vec::new();
    if let Some(parent_name) = &section.inherits {
        let parent_index = sections
            .iter()
            .position(|candidate| candidate.name == *parent_name)
            .ok_or_else(|| {
                format!(
                    "section '{}' inherits unknown section '{}'",
                    section.name, parent_name
                )
            })?;
        if sections[parent_index].inherits.is_some() {
            return Err(format!(
                "section '{}' inherits through '{}' more than one level",
                section.name, parent_name
            ));
        }
        fields.extend(sections[parent_index].fields.iter().cloned());
    }
    for (key, value) in &section.fields {
        if let Some((_, existing_value)) = fields.iter_mut().find(|(existing_key, _)| existing_key == key) {
            *existing_value = value.clone();
        } else {
            fields.push((key.clone(), value.clone()));
        }
    }
    Ok(fields)
}

fn fail(message: impl AsRef<str>) -> ! {
    eprintln!("{}", message.as_ref());
    process::exit(1);
}

fn main() {
    let mut arguments = env::args();
    arguments.next();
    let path = arguments.next().unwrap_or_else(|| fail("missing records.cfg path"));
    let data = fs::read_to_string(&path)
        .unwrap_or_else(|error| fail(format!("cannot read '{}': {}", path, error)));
    let sections = parse(&data).unwrap_or_else(|message| fail(message));
    let mut output = String::new();
    for index in 0..sections.len() {
        let fields = resolve(index, &sections).unwrap_or_else(|message| fail(message));
        for (key, value) in fields {
            output.push_str(&sections[index].name);
            output.push('.');
            output.push_str(&key);
            output.push('=');
            output.push_str(&value);
            output.push('\n');
        }
    }
    print!("{}", output);
}
